import numpy as np
l=open('optcon.xyz').read().splitlines();a=[]
for x in l[2:]:
 s=x.split(); a.append((s[0],np.array(list(map(float,s[1:4])))))
C=a[0][1]
print('Cr',C)
ns=[10,11,49,50]
for i in ns: print(i,a[i][1]-C,np.linalg.norm(a[i][1]-C))
for i in ns:
 for j in ns:
  if j>i:
   v=a[i][1]-C;w=a[j][1]-C
   print(i,j,'angle',np.degrees(np.arccos(np.dot(v,w)/np.linalg.norm(v)/np.linalg.norm(w))))
